{"content": "1|/**
2| * hermes-turn-hook.ts — Hermes's native per-turn hook for the brain-first
3| * rule: a marked `hooks.pre_llm_call` shell hook in $HERMES_HOME/config.yaml
4| * that echoes `{"context": <rule>}`, which Hermes appends to every user
5| * message. The block in SOUL.md reaches the system prompt only, and bots read
6| * it as identity; this puts the same rule next to each turn. The command is
7| * self-contained (no gbrain process per turn, no path that must exist on the
8| * Hermes host), so a re-run after an upgrade rewrites it with the new text.
9| *
10| * Ownership is by YAML comment markers; text outside them is never touched.
11| * gbrain appends its block only when config.yaml has no top-level `hooks:`
12| * key (a second one would be invalid YAML) and prints the entry to add by
13| * hand otherwise. Hermes runs a shell hook only after approval, so setup
14| * records the approval for this exact command in Hermes's own allowlist, the
15| * way `gbrain setup codex` writes its hook trust entries. Removal strips the
16| * block and that approval.
17| *
18| * The same block also carries the skill-resolver lane's entry
19| * (`gbrain setup hermes --skill-loading resolve`, skill-resolver-hook.ts):
20| * config.yaml can hold one top-level `hooks:` key, so both lanes share one
21| * marked block, each entry with its own approval. Each lane writes and removes
22| * only its own entry, so declining the brain-first rule keeps the resolver
23| * and the reverse; the block goes when its last entry does.
24| */
25|import { existsSync, readFileSync } from 'node:fs';
26|import { join } from 'node:path';
27|import { atomicWriteTextFile } from '../bootstrap/atomic-write.ts';
28|import { acquireNativeLockSync } from '../persistence/native-lock.ts';
29|import { loadBoundedYaml } from '../data-frontmatter.ts';
30|import { probeBlock, removeBlock, spliceBlock, type BlockMarkers } from '../managed-block.ts';
31|import { renderBrainFirstTurnRule, writeUnlessChanged, type BrainFirstAccess } from './brain-first.ts';
32|import { isSkillResolverCommand } from './skill-resolver-lane.ts';
33|
34|const MARKERS: BlockMarkers = { begin: '# gbrain:turn-rule:begin', end: '# gbrain:turn-rule:end', label: 'turn-rule', rerun: 'gbrain setup hermes --instructions-only' };
35|const EVENT = 'pre_llm_call';
36|const ALLOWLIST = 'shell-hooks-allowlist.json';
37|
38|export interface HermesTurnHookOutcome { action: 'write' | 'keep' | 'print' | 'remove' | 'skip'; path: string; detail: string; snippet?: string }
39|
40|/** `/bin/echo '<json>'`: Hermes splits the command without a shell (and checks the first path, /bin/echo, exists), and a quote in the rule is a JSON escape. */
41|export function hermesTurnHookCommand(access: BrainFirstAccess): string {
42|  return `/bin/echo '${JSON.stringify({ context: renderBrainFirstTurnRule(access, 'hermes') }).replace(/'/g, '\\u0027')}'`;
43|}
44|
45|/** The lanes that own an entry in gbrain's block, in the order the block lists them, with each entry's timeout. */
46|export type HermesHookLane = 'turn-rule' | 'skill-resolver';
47|const LANES: Record<HermesHookLane, { timeout: number; what: string }> = {
48|  'turn-rule': { timeout: 10, what: 'per-turn rule hook' },
49|  'skill-resolver': { timeout: 15, what: 'skill-resolver lane hook' },
50|};
51|const laneOf = (command: string): HermesHookLane => (isSkillResolverCommand(command) ? 'skill-resolver' : 'turn-rule');
52|
53|/** Each lane's command in the block (the first entry of each lane). */
54|function entriesIn(interior: string | undefined): Partial<Record<HermesHookLane, string>> {
55|  const out: Partial<Record<HermesHookLane, string>> = {};
56|  for (const m of (interior ?? '').matchAll(/command: (".*")/g)) {
57|    const command = JSON.parse(m[1]!) as string;
58|    out[laneOf(command)] ??= command;
59|  }
60|  return out;
61|}
62|
63|const commandIn = (interior: string | undefined): string | null => entriesIn(interior)['turn-rule'] ?? null;
64|
65|function hooksYaml(entries: Partial<Record<HermesHookLane, string>>): string {
66|  const items = (Object.keys(LANES) as HermesHookLane[]).flatMap((lane) => (entries[lane] ? [`    - command: ${JSON.stringify(entries[lane])}\n      timeout: ${LANES[lane].timeout}\n`] : []));
67|  return `hooks:\n  ${EVENT}:\n${items.join('')}`;
68|}
69|
70|interface Allowlist { approvals: Array<Record<string, unknown>> }
71|
72|/** Throws on a file gbrain cannot read as Hermes does (utf-8-sig JSON object), so it is never rewritten without the user's approvals. */
73|function readAllowlist(path: string): Allowlist {
74|  if (!existsSync(path)) return { approvals: [] };
75|  const raw = JSON.parse(readFileSync(path, 'utf8').replace(/^\uFEFF/, '')) as Allowlist;
76|  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new Error(`${ALLOWLIST} is not a JSON object`);
77|  return Array.isArray(raw.approvals) ? raw : { ...raw, approvals: [] };
78|}
79|
80|const approves = (e: Record<string, unknown>, command: string) => e.event === EVENT && e.command === command;
81|
82|/**
83| * Read-modify-write the allowlist under Hermes's own lock: an exclusive
84| * flock(2) on the sibling `shell-hooks-allowlist.json.lock` (Hermes's
85| * agent/shell_hooks.py `_locked_update_approvals`), so an approval Hermes
86| * records at the same moment is never lost. Fails closed: a lock held past
87| * the wait, or no lock primitive on this host, throws and writes nothing.
88| */
89|function withAllowlistLock(path: string, update: (list: Allowlist) => Allowlist | null): void {
90|  const lockPath = `${path}.lock`;
91|  const lock = acquireNativeLockSync(lockPath, { timeoutMs: 3000 });
92|  if (!lock) throw new Error(`Hermes holds ${lockPath}; ${ALLOWLIST} was not changed. Run setup again once Hermes is idle`);
93|  try {
94|    const next = update(readAllowlist(path));
95|    if (next) atomicWriteTextFile(path, `${JSON.stringify(next, null, 2)}\n`, { freshMode: 0o600 });
96|  } finally {
97|    lock.release();
98|  }
99|}
100|
101|function approve(hermesHome: string, command: string): void {
102|  withAllowlistLock(join(hermesHome, ALLOWLIST), (list) => {
103|    if (list.approvals.some((e) => approves(e, command))) return null;
104|    list.approvals.push({ event: EVENT, command, approved_at: new Date().toISOString(), script_mtime_at_approval: null });
105|    return list;
106|  });
107|}
108|
109|function revoke(hermesHome: string, command: string): void {
110|  const path = join(hermesHome, ALLOWLIST);
111|  if (!existsSync(path)) return;
112|  withAllowlistLock(path, (list) => {
113|    const kept = list.approvals.filter((e) => !approves(e, command));
114|    return kept.length === list.approvals.length ? null : { ...list, approvals: kept };
115|  });
116|}
117|
118|/** Write or update the hook (accepted decision). Never throws: anything gbrain cannot edit safely is printed to add by hand. */
119|export function syncHermesTurnHook(opts: { hermesHome: string; access: BrainFirstAccess; dryRun: boolean }): HermesTurnHookOutcome {
120|  return syncHermesHook({ hermesHome: opts.hermesHome, lane: 'turn-rule', command: hermesTurnHookCommand(opts.access), dryRun: opts.dryRun });", "total_lines": 241, "file_size": 14582, "truncated": true, "hint": "Use offset=121 to continue reading (showing 1-120 of 241 lines)", "is_binary": false, "is_image": false}

